declare p jsonb := '[{"book":"gatsby","id":"canada","collection":"cited","name":"Canada","noteHash":"1e65335f06f936602032d7b068584b05","positionSource":"df6f72ca81518a46323744b55f4eec4a1a0b57cbf0765eec9d7c4203510f7e59","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"A rumour about an underground pipeline to Canada becomes part of Gatsby’s public legend.","it":"Una voce su una conduttura sotterranea verso il Canada entra nella leggenda pubblica di Gatsby.","fr":"Une rumeur de canalisation souterraine vers le Canada entre dans la légende publique de Gatsby.","es":"Un rumor sobre una tubería subterránea hacia Canadá entra en la leyenda pública de Gatsby."}}},{"book":"gatsby","id":"germany","collection":"cited","name":"Germany","noteHash":"697fb411078ec51eb74030df3f483af2","positionSource":"4346cbbb2d2a9bfd6e0bbb0d36a761734906fe7a8ac7de29a1176056e19c5164","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"One guest claims to have heard Gatsby’s story from a man who grew up with him in Germany.","it":"Un invitato sostiene di aver sentito la storia di Gatsby da un uomo cresciuto con lui in Germania.","fr":"Un invité affirme avoir entendu l’histoire de Gatsby d’un homme qui a grandi avec lui en Allemagne.","es":"Un invitado afirma haber oído la historia de Gatsby de un hombre que creció con él en Alemania."}}},{"book":"gatsby","id":"grandcanal","collection":"cited","name":"Grand Canal · Venice","noteHash":"1e65335f06f936602032d7b068584b05","positionSource":"8263be15110b8e22c60ee93a3b55bbd959e0efeeb1c5d7d76618d2412b445943","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Nick imagines Gatsby’s extravagant account as a palace on the Grand Canal in Venice.","it":"Nick immagina il racconto stravagante di Gatsby come un palazzo sul Canal Grande a Venezia.","fr":"Nick imagine le récit extravagant de Gatsby comme un palais sur le Grand Canal à Venise.","es":"Nick imagina el relato extravagante de Gatsby como un palacio en el Gran Canal de Venecia."}}},{"book":"gatsby","id":"jerseycity","collection":"cited","name":"Jersey City","noteHash":"1e65335f06f936602032d7b068584b05","positionSource":"4b39fc3cc4bcc3da350d242a4710d4ffed018af6cd9183c1972c3422cc279750","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Nick remembers a brief relationship with a woman who lived in Jersey City.","it":"Nick ricorda una breve relazione con una donna che viveva a Jersey City.","fr":"Nick se souvient d’une brève liaison avec une femme qui vivait à Jersey City.","es":"Nick recuerda una breve relación con una mujer que vivía en Jersey City."}}},{"book":"gatsby","id":"louisiana","collection":"cited","name":"Louisiana","noteHash":"1e65335f06f936602032d7b068584b05","positionSource":"688b11484b2de2dc4912bb15a497ef8b2c9e69f8593cd9e477b6b313120d7fb3","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Nick imagines Louisiana’s swamps as one of the possible origins he might have accepted for Gatsby.","it":"Nick immagina le paludi della Louisiana come una delle possibili origini che avrebbe accettato per Gatsby.","fr":"Nick imagine les marais de Louisiane parmi les origines possibles qu’il aurait acceptées pour Gatsby.","es":"Nick imagina los pantanos de Luisiana como uno de los posibles orígenes que habría aceptado para Gatsby."}}},{"book":"gatsby","id":"lowereast","collection":"cited","name":"Lower East Side","noteHash":"1e65335f06f936602032d7b068